CREATE   PROCEDURE [synapse_ce].[usp_Insert_apuk_employmentrelationship]
AS
BEGIN
	INSERT INTO [synapse_ce].[apuk_employmentrelationship]
	(
		[apuk_accountid],
		[apuk_accountid_entitytype],
		[apuk_accountidname],
		[apuk_accountidyominame],
		[apuk_businessemailaddress],
		[apuk_businessphonenumber],
		[apuk_contactid],
		[apuk_contactid_entitytype],
		[apuk_contactidname],
		[apuk_contactidyominame],
		[apuk_employmentrelationshipid],
		[apuk_enddate],
		[apuk_jobtitle],
		[apuk_name],
		[apuk_primaryemployment],
		[apuk_publishindirectory],
		[apuk_relationshiptype],
		[apuk_startdate],
		[apuk_workexperience],
		[createdby],
		[createdby_entitytype],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[createdonbehalfby],
		[createdonbehalfby_entitytype],
		[createdonbehalfbyname],
		[createdonbehalfbyyominame],
		[Id],
		[importsequencenumber],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		[modifiedonbehalfby],
		[modifiedonbehalfby_entitytype],
		[modifiedonbehalfbyname],
		[modifiedonbehalfbyyominame],
		[organizationid],
		[organizationid_entitytype],
		[organizationidname],
		[overriddencreatedon],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[statecode],
		[statuscode],
		[timezoneruleversionnumber],
		[utcconversiontimezonecode],
		[versionnumber]
	)
	SELECT 
		stg.[apuk_accountid],
		stg.[apuk_accountid_entitytype],
		stg.[apuk_accountidname],
		stg.[apuk_accountidyominame],
		stg.[apuk_businessemailaddress],
		stg.[apuk_businessphonenumber],
		stg.[apuk_contactid],
		stg.[apuk_contactid_entitytype],
		stg.[apuk_contactidname],
		stg.[apuk_contactidyominame],
		stg.[apuk_employmentrelationshipid],
		stg.[apuk_enddate],
		stg.[apuk_jobtitle],
		stg.[apuk_name],
		stg.[apuk_primaryemployment],
		stg.[apuk_publishindirectory],
		stg.[apuk_relationshiptype],
		stg.[apuk_startdate],
		stg.[apuk_workexperience],
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[Id],
		stg.[importsequencenumber],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[organizationid],
		stg.[organizationid_entitytype],
		stg.[organizationidname],
		stg.[overriddencreatedon],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[statecode],
		stg.[statuscode],
		stg.[timezoneruleversionnumber],
		stg.[utcconversiontimezonecode],
		stg.[versionnumber]	
	FROM [staging_ce].[apuk_employmentrelationship] stg
		LEFT JOIN [synapse_ce].[apuk_employmentrelationship] tgt
			ON tgt.[id] = stg.[id]
	WHERE tgt.[id] IS NULL
END
